SELECT * FROM(select * from yh_life_habit_sign
where
	user_code=#{userCode,jdbcType=VARCHAR}
		and signId_date between #{signidDate} and #{signidDate1}

	) AS b GROUP BY b.signId_date order by signId_date asc

select max(days) incessancy_days
from
(
select user_code
,@cont_day :=
(
case when (@last_uid = user_code and DATEDIFF(ot, @last_ot)=1) then
(@cont_day + 1)
when (@last_uid = user_code and DATEDIFF(ot, @last_ot)<1) then
(@cont_day + 0)
else 1
end
) as days
,(@cont_ix := (@cont_ix + if(@cont_day = 1, 1, 0))) AS cont_ix
,@last_uid := user_code
,@last_ot := ot ot
from
(
select user_code
,signId_date as ot
from yh_life_habit_sign
where signId_date >= #{signidDate}
and signId_date <= #{signidDate1}
and user_code=#{userCode,jdbcType=VARCHAR}
order by user_code ,signId_date
) as t1,
(
select @last_uid := '',
@last_ot  := '',
@cont_ix  := 0,
@cont_day := 0
) as t2
) as t
group by user_code;

select max(days) incessancy_days
from
(
select user_code
,@cont_day :=
(
case when (@last_uid = user_code and DATEDIFF(ot, @last_ot)=1) then
(@cont_day + 1)
when (@last_uid = user_code and DATEDIFF(ot, @last_ot)<1) then
(@cont_day + 0)
else 1
end
) as days
,(@cont_ix := (@cont_ix + if(@cont_day = 1, 1, 0))) AS cont_ix
,@last_uid := user_code
,@last_ot := ot ot
from
(
select user_code
,signId_date as ot
from yh_life_habit_sign
where signId_date >= #{signidDate}
and signId_date <= #{signidDate1}
and habit_id=#{habitId,jdbcType=INTEGER}
and user_code=#{userCode,jdbcType=VARCHAR}
order by user_code ,signId_date
) as t1,
(
select @last_uid := '',
@last_ot  := '',
@cont_ix  := 0,
@cont_day := 0
) as t2
) as t
group by user_code;


